        RustLib.instance.api.rust_arc_decrement_strong_count_Session,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_SessionPtr,
  );

  /// Adds a WAV or FLAC recording of the person (format detected from the
  /// bytes). The transcript is optional.
  Future<SampleSummary> addSample({
    required String speakerId,
    required List<int> audio,
    String? transcript,
  }) => RustLib.instance.api.crateApiSessionSessionAddSample(
    that: this,
    speakerId: speakerId,
    audio: audio,
    transcript: transcript,
  );

  /// Generates (or regenerates) the person's voice from all their samples.
  Future<VoiceSummary> buildVoice({required String speakerId}) => RustLib
      .instance
      .api
      .crateApiSessionSessionBuildVoice(that: this, speakerId: speakerId);

  String get engineName =>
      RustLib.instance.api.crateApiSessionSessionEngineName(that: this);

  List<SpeakerSummary> listSpeakers() =>
      RustLib.instance.api.crateApiSessionSessionListSpeakers(that: this);

  /// Registers a person; `consent_by` (who authorized the use of the
  /// voice) is mandatory. Default language: pt-BR.
  SpeakerSummary registerSpeaker({
    required String name,
    String? relationship,
    String? consentBy,
    String? language,
  }) => RustLib.instance.api.crateApiSessionSessionRegisterSpeaker(
    that: this,
    name: name,
    relationship: relationship,
    consentBy: consentBy,
    language: language,
  );

  /// Speaks a message now in the person's voice and returns the WAV path.
  Future<SpokenMessage> speak({
    required String speakerId,
    String? theme,
    String? text,
    String? toneStyle,
    required double pitchShift,
    String? listener,
  }) => RustLib.instance.api.crateApiSessionSessionSpeak(
    that: this,
    speakerId: speakerId,
    theme: theme,
    text: text,
    toneStyle: toneStyle,
    pitchShift: pitchShift,
    listener: listener,
  );
}
